    meaning: "The Most High",
    place: "makkah",
    ayahs: [
      { number: 1, arabic: "سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى", translation: "Praise the Name of your Lord, the Most High." },
      { number: 2, arabic: "الَّذِي خَلَقَ فَسَوَّىٰ", translation: "He who creates and regulates." },
      { number: 3, arabic: "وَالَّذِي قَدَّرَ فَهَدَىٰ", translation: "He who measures and guides." },
      { number: 4, arabic: "وَالَّذِي أَخْرَجَ الْمَرْعَىٰ", translation: "He who produces the pasture." },
      { number: 5, arabic: "فَجَعَلَهُ غُثَاءً أَحْوَىٰ", translation: "And then turns it into light debris." },
      { number: 6, arabic: "سَنُقْرِئُكَ فَلَا تَنسَىٰ", translation: "We will make you read, so do not forget." },
      { number: 7, arabic: "إِلَّا مَا شَاءَ اللَّهُ ۚ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَىٰ", translation: "Except what Allah wills. He knows what is declared, and what is hidden." },
      { number: 8, arabic: "وَنُيَسِّرُكَ لِلْيُسْرَىٰ", translation: "We will ease you into the Easy Way." },
      { number: 9, arabic: "فَذَكِّرْ إِن نَّفَعَتِ الذِّكْرَىٰ", translation: "So remind, if reminding helps." },
      { number: 10, arabic: "سَيَذَّكَّرُ مَن يَخْشَىٰ", translation: "The reverent will remember." },
      { number: 11, arabic: "وَيَتَجَنَّبُهَا الْأَشْقَى", translation: "But the wretched will avoid it." },
      { number: 12, arabic: "الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ", translation: "He who will enter the Gigantic Fire." },
      { number: 13, arabic: "ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ", translation: "Where he will neither die, nor live." },
      { number: 14, arabic: "قَدْ أَفْلَحَ مَن تَزَكَّىٰ", translation: "Successful is he who purifies himself." },
      { number: 15, arabic: "وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّىٰ", translation: "And mentions the name of his Lord, and prays." },
      { number: 16, arabic: "بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا", translation: "But you prefer the present life." },
      { number: 17, arabic: "وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ", translation: "Though the Hereafter is better, and more lasting." },
      { number: 18, arabic: "إِنَّ هَٰذَا لَفِي الصُّحُفِ الْأُولَىٰ", translation: "This is in the former scriptures." },
      { number: 19, arabic: "صُحُفِ إِبْرَاهِيمَ وَمُوسَىٰ", translation: "The Scriptures of Abraham and Moses." },
    ],
